(229, 'astra-sites-and-pages-page-12', 'a:15:{s:8:\"id-57022\";a:22:{s:5:\"title\";s:9:\"Tech News\";s:2:\"id\";i:57022;s:12:\"publish-date\";i:1626294756;s:18:\"featured-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2021/07/tech-news-04-home.jpg\";s:19:\"thumbnail-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2021/07/tech-news-04-home.jpg\";s:28:\"fullpage-thumbnail-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2021/07/tech-news-04-home.jpg\";s:14:\"astra-site-url\";s:31:\"//websitedemos.net/tech-news-04\";s:20:\"astra-site-parent-id\";i:2260;s:15:\"astra-sites-tag\";a:9:{i:480;s:4:\"blog\";i:2275;s:13:\"business-blog\";i:2277;s:17:\"business-magazine\";i:2276;s:13:\"business-news\";i:2273;s:9:\"editorial\";i:2274;s:8:\"magazine\";i:2271;s:4:\"news\";i:2272;s:10:\"publishing\";i:2278;s:16:\"publishing-house\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:37;s:4:\"blog\";}s:29:\"astra-sites-template-category\";a:3:{i:2828;s:4:\"blog\";i:2774;s:8:\"magazine\";i:2859;s:4:\"news\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:1:{i:2497;s:4:\"blog\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}i:2;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1070:\"<!-- wp:paragraph -->\n<p>Build a technology website using the Tech News template and share the latest trends related to technology, gadgets, software, apps, games, and more. The clean and clutter-free design will help your website visitors find what they\'re looking for without digging through piles of information.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The template features a newsletter subscription form that will let you build your newsletter list quickly and easily.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Tech News template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Simple and clutter-free website template, perfect for a technology website</li><li>The package includes well-planned layouts for individual category pages as well</li><li>Build an email list using the well-integrated newsletter subscription form</li><li>The template consists of placeholders for showcasing ads and monetizing your blog</li><li>Compatible with Gutenberg and all popular page builder plugins</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:75:\"Clean and simple website template, perfect for your technology news website\";s:5:\"pages\";a:4:{s:8:\"id-57023\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:74:\"https://websitedemos.net/wp-content/uploads/2021/07/tech-news-04-about.jpg\";s:19:\"thumbnail-image-url\";s:74:\"https://websitedemos.net/wp-content/uploads/2021/07/tech-news-04-about.jpg\";s:18:\"astra-page-api-url\";s:61:\"https://websitedemos.net/tech-news-04/wp-json/wp/v2/pages/705\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:38:\"//websitedemos.net/tech-news-04/about/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:74;s:4:\"blog\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-57024\";a:12:{s:5:\"title\";s:7:\"Contact\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2021/07/tech-news-04-contact.jpg\";s:19:\"thumbnail-image-url\";s:76:\"https://websitede