 builders</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:80:\"Professional web template ideal for businesses that like to show as well as tell\";s:5:\"pages\";a:5:{s:8:\"id-47141\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:75:\"https://websitedemos.net/wp-content/uploads/2020/08/event-management-02.jpg\";s:19:\"thumbnail-image-url\";s:75:\"https://websitedemos.net/wp-content/uploads/2020/08/event-management-02.jpg\";s:18:\"astra-page-api-url\";s:67:\"https://websitedemos.net/event-management-04/wp-json/wp/v2/pages/19\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:39:\"//websitedemos.net/event-management-04/\";s:15:\"astra-sites-tag\";a:2:{i:423;s:4:\"home\";i:814;s:8:\"homepage\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-47143\";a:12:{s:5:\"title\";s:5:\"Works\";s:18:\"featured-image-url\";s:81:\"https://websitedemos.net/wp-content/uploads/2020/08/event-management-02-works.jpg\";s:19:\"thumbnail-image-url\";s:81:\"https://websitedemos.net/wp-content/uploads/2020/08/event-management-02-works.jpg\";s:18:\"astra-page-api-url\";s:68:\"https://websitedemos.net/event-management-04/wp-json/wp/v2/pages/167\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:45:\"//websitedemos.net/event-management-04/works/\";s:15:\"astra-sites-tag\";a:3:{i:444;s:9:\"portfolio\";i:1613;s:8:\"projects\";i:451;s:4:\"work\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:1:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s