(267, 'astra-sites-and-pages-page-27', 'a:15:{s:8:\"id-20746\";a:22:{s:5:\"title\";s:15:\"Pearson College\";s:2:\"id\";i:20746;s:12:\"publish-date\";i:1551330893;s:18:\"featured-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2019/07/education-04-home.jpg\";s:19:\"thumbnail-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2019/07/education-04-home.jpg\";s:28:\"fullpage-thumbnail-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2019/07/education-04-home.jpg\";s:14:\"astra-site-url\";s:31:\"//websitedemos.net/education-04\";s:20:\"astra-site-parent-id\";i:187;s:15:\"astra-sites-tag\";a:5:{i:457;s:7:\"college\";i:459;s:9:\"education\";i:460;s:8:\"learning\";i:456;s:6:\"school\";i:458;s:10:\"university\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:27;s:8:\"business\";}s:29:\"astra-sites-template-category\";a:3:{i:2825;s:8:\"coaching\";i:2840;s:18:\"college-university\";i:2772;s:9:\"education\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:1:{i:2491;s:22:\"educational-institutes\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}i:2;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1015:\"<!-- wp:paragraph -->\n<p>The Pearson College template is a calm, confident design that uses lots of whitespace and images to help tell the story. There are also some nice effects, inspiring fonts and a nice green contrast color to highlight specific areas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The template has a laid back feel but with the authority this niche commands, along with fully customizable content areas, supplementary pages and contact form. As always, you can fully customize everything you see on the page to fit your brand.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Pearson College template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><li>Calm, relaxed web template ideal for colleges or universities</li><li>Flexible content areas throughout</li><li>Popular pages already designed and provided in the template</li><li>Lots of options to use images to paint a picture</li><li>Full compatibility with leading page builders</li></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:79:\"Education template with an accessible feel and great design, ideal for colleges\";s:5:\"pages\";a:6:{s:8:\"id-23876\";a:12:{s:5:\"title\";s:4:\"Home\";s:18:\"featured-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2019/07/education-04-home.jpg\";s:19:\"thumbnail-image-url\";s:73:\"https://websitedemos.net/wp-content/uploads/2019/07/education-04-home.jpg\";s:18:\"astra-page-api-url\";s:59:\"https://websitedemos.net/education-04/wp-json/wp/v2/pages/5\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:32:\"//websitedemos.net/education-04/\";s:15:\"astra-sites-tag\";a:1:{i:423;s:4:\"home\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}}}s:8:\"id-23871\";a:12:{s:5:\"title\";s:5:\"About\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2019/07/education-04-about-2.jpg\";s:19:\"thumbnail-image-ur