(572, 1, '2023-01-31 20:06:49', '2023-02-01 00:06:49', '{\"fields\":[{\"id\":\"0\",\"type\":\"name\",\"label\":\"Your Name \",\"format\":\"simple\",\"description\":\"\",\"required\":\"1\",\"size\":\"large\",\"simple_placeholder\":\"Your Name \",\"simple_default\":\"\",\"first_placeholder\":\"\",\"first_default\":\"\",\"middle_placeholder\":\"\",\"middle_default\":\"\",\"last_placeholder\":\"\",\"last_default\":\"\",\"css\":\"\",\"label_hide\":\"1\"},{\"id\":\"1\",\"type\":\"email\",\"label\":\"Email\",\"description\":\"\",\"required\":\"1\",\"size\":\"large\",\"placeholder\":\"Email Address\",\"confirmation_placeholder\":\"\",\"default_value\":false,\"filter_type\":\"\",\"allowlist\":\"\",\"denylist\":\"\",\"css\":\"\",\"label_hide\":\"1\"},{\"id\":\"2\",\"type\":\"textarea\",\"label\":\"Your Message\",\"description\":\"\",\"required\":\"1\",\"size\":\"medium\",\"placeholder\":\"Message\",\"limit_count\":\"1\",\"limit_mode\":\"characters\",\"default_value\":\"\",\"css\":\"\",\"label_hide\":\"1\"}],\"id\":\"10\",\"field_id\":5,\"settings\":{\"form_title\":\"Contact Form\",\"form_desc\":\"\",\"submit_text\":\"SEND MESSAGE\",\"submit_text_processing\":\"Sending...\",\"form_class\":\"\",\"submit_class\":\"\",\"notification_enable\":\"1\",\"notifications\":{\"1\":{\"email\":\"{admin_email}\",\"subject\":\"Han llenado el formulario de contacto\",\"sender_name\":\"{field_id=\\\"0\\\"}\",\"sender_address\":\"{admin_email}\",\"replyto\":\"{field_id=\\\"1\\\"}\",\"message\":\"{all_fields}\"}},\"confirmations\":{\"1\":{\"type\":\"message\",\"message\":\"<p>Thanks for contacting us! We will be in touch with you shortly.<\\/p>\",\"message_scroll\":\"1\",\"page\":\"7\",\"redirect\":\"\"}},\"honeypot\":\"1\",\"form_tags\":[]},\"meta\":{\"template\":\"contact\"}}', 'Contact Form', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2023-01-31 20:06:49', '2023-02-01 00:06:49', '', 10, 'http://localhost/wordpress/?p=572', 0, 'revision', '', 0),
